// Balance authors across the full cycle, without duplicate draws.
(function () {
  var groups = {}, ordered = [], total = HUB_DATA.quotes.length, last = '';
  HUB_DATA.quotes.forEach(function (q) { (groups[q.author] || (groups[q.author] = [])).push(q); });
  while (ordered.length < total) {
    var available = Object.keys(groups).filter(function (author) { return groups[author].length && author !== last; });
    if (!available.length) available = Object.keys(groups).filter(function (author) { return groups[author].length; });
    available.sort(function (a, b) { return groups[b].length - groups[a].length || a.localeCompare(b); });
    last = available[0]; ordered.push(groups[last].shift());
  }
  HUB_DATA.quotes = ordered;
}());
